import{_ as p,a0 as n,w as d,s as l,ao as s,I as i,x as r,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何解压 tar 文件到不同的目录中 | LCTT x X-CMD","titleTemplate":false,"description":"如何解压 tar 文件到不同的目录中 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解压 tar 文件到不同的目录中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解压 tar 文件到不同的目录中 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems","title":"如何解压 tar 文件到不同的目录中","tag":"201502","desc":""},"relativePath":"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems.md","filePath":"[post].md"}'),f={name:"201502/20150115 How To Extract a Tar Files To a Different Directory on a Linux or Unix-like Systems.md"};function m(x,t,c,u,T,b){const a=n("Link");return d(),l("div",null,[t[13]||(t[13]=s(`<h1 id="如何解压-tar-文件到不同的目录中" tabindex="-1">如何解压 tar 文件到不同的目录中 <a class="header-anchor" href="#如何解压-tar-文件到不同的目录中" aria-label="Permalink to “如何解压 tar 文件到不同的目录中”">​</a></h1><p>我想要解压一个tar文件到一个叫/tmp/data的指定目录。我该如何在Linux或者类Unix的系统中使用tar命令解压一个tar文件到不同的目录中？</p><p>你不必使用cd命令切换到其他的目录并解压。可以使用下面的语法解压一个文件：</p><h3 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to “语法”">​</a></h3><p>典型Unix tar语法：</p><pre><code>tar -xf file.name.tar -C /path/to/directory
</code></pre><p>GNU/tar 语法：</p><pre><code>tar xf file.tar -C /path/to/directory

tar xf file.tar --directory /path/to/directory
</code></pre><h3 id="示例-解压文件到另一个目录中" tabindex="-1">示例：解压文件到另一个目录中 <a class="header-anchor" href="#示例-解压文件到另一个目录中" aria-label="Permalink to “示例：解压文件到另一个目录中”">​</a></h3><p>在本例中。我解压$HOME/etc.backup.tar到/tmp/data目录中。首先，需要手动创建这个目录，输入：</p><pre><code>mkdir /tmp/data
</code></pre><p>要解压$HOME/etc.backup.tar 到/tmp/data中，输入：</p><pre><code>tar -xf $HOME/etc.backup.tar -C /tmp/data
</code></pre><p>要看到进度，使用-v选项：</p><pre><code>tar -xvf $HOME/etc.backup.tar -C /tmp/data
</code></pre><p>示例输出：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2015/01/tar-extract-archive-to-dir.gif" alt="Gif 01: tar Command Extract Archive To Different Directory Command"></p><p><em>Gif 01: tar命令解压文件到不同的目录</em></p><p>你也可以指定解压的文件：</p><pre><code>tar -xvf $HOME/etc.backup.tar file1 file2 file3 dir1 -C /tmp/data
</code></pre><p>要解压foo.tar.gz（.tgz扩展文件）包到/tmp/bar中，输入：</p><pre><code>mkdir /tmp/bar
tar -zxvf foo.tar.gz -C /tmp/bar
</code></pre><p>要解压foo.tar.bz2（.tbz, .tbz2 和 .tb2 扩展文件）包到/tmp/bar中，输入：</p><pre><code>mkdir /tmp/bar
tar -jxvf foo.tar.bz2  -C /tmp/bar
</code></pre><hr>`,25)),i("p",null,[t[1]||(t[1]=r("via: ",-1)),e(a,{href:"http://www.cyberciti.biz/faq/howto-extract-tar-file-to-specific-directory-on-unixlinux/"},{default:o(()=>[...t[0]||(t[0]=[r("http://www.cyberciti.biz/faq/howto-extract-tar-file-to-specific-directory-on-unixlinux/",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=r("作者：",-1)),e(a,{href:"http://www.cyberciti.biz/tips/about-us"},{default:o(()=>[...t[2]||(t[2]=[r("nixCraft",-1)])]),_:1}),t[6]||(t[6]=r(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:o(()=>[...t[3]||(t[3]=[r("geekpi",-1)])]),_:1}),t[7]||(t[7]=r(" 校对：",-1)),e(a,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[4]||(t[4]=[r("Caroline",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=r("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[r("LCTT",-1)])]),_:1}),t[11]||(t[11]=r(" 原创翻译，",-1)),e(a,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[r("Linux中国",-1)])]),_:1}),t[12]||(t[12]=r(" 荣誉推出",-1))])])}const _=p(f,[["render",m]]);export{y as __pageData,_ as default};
